import type { MetadataRoute } from "next";
import { site } from "@/lib/site";

/** Web app manifest: name, colours and the official Localians icons (generated by scripts/build-brand-assets.mjs). */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "Localians",
    short_name: "Localians",
    description: site.description,
    start_url: "/dashboard",
    scope: "/",
    display: "standalone",
    background_color: "#070907",
    theme_color: "#070907",
    icons: [
      { src: "/images/logo/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/images/logo/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/images/logo/icon-maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
  };
}
